def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    comps = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            comps.setdefault(color, []).append(comp)
    # Recolor the smallest disconnected component of the most prevalent foreground color.
    color = max(comps, key=lambda k: sum(len(c) for c in comps[k]))
    comp = min(comps[color], key=len)
    for r, c in comp:
        out[r][c] = 0
    return out
