            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.setdefault(color, []).append(comp)
    # In these grids the distinctive tiny topmost component is the marker;
    # it takes the color of the large irregular object.
    largest_color = max(comps, key=lambda col: max(map(len, comps[col])))
    largest = max(comps[largest_color], key=len)
    target = min((p for cc in comps.values() for p in cc), key=lambda p: min(r for r,c in p))
    for r, c in target:
        out[r][c] = largest_color
    return out
